import * as React from "react"
import { graphql, Link } from "gatsby"
import Layout from "../../components/layout"

export default function BlogPostTemplate({
  data,
}) {
  const { markdownRemark } = data
  const { frontmatter, html } = markdownRemark
  return (
    <Layout>
      <div>
        <p>
        <h1 className="reduced-bottom-margin">{frontmatter.title}</h1>
        <small>{frontmatter.tags.map(tag => <span style={{"display": "inline-block", "marginRight": "0.5rem",}}><code><Link to={"/tags/" + tag.toLowerCase()} className="redirect">{tag}</Link></code></span>)}</small>
        </p>
        <div
          dangerouslySetInnerHTML={{ __html: html }}
        />
      </div>
      <p><small>Written on {frontmatter.dateCreated}. Last updated on {frontmatter.dateUpdated}.</small></p>
      <p><Link to="/blog" className="redirect">☞ Go back to the blog page</Link></p>
    </Layout>
  )
}

export const pageQuery = graphql`
  query($id: String!) {
    markdownRemark(id: { eq: $id }) {
      html
      frontmatter {
        slug
        title
        tags
        dateCreated
        dateUpdated
      }
    }
  }
`